import { Settings } from 'lucide-react';
import { Button } from './ui/button';

const TopNavigation = () => {
  return (
    <nav className="top-navigation">
      <div className="top-nav-content">
        <div className="top-nav-left" />

        <div className="top-nav-right">
          <div className="nav-links">
            <a href="#" className="nav-link">Search for Jobs</a>
            <a href="#" className="nav-link">Candidate Home</a>
            <a href="#" className="nav-link">Job Alerts</a>
          </div>

          <span className="nav-email">yaswanthkumarchekuri@gmail.com</span>

          <Button variant="ghost" size="icon" className="nav-icon-button" aria-label="Settings">
            <Settings className="icon" />
          </Button>
        </div>
      </div>

      <style jsx="true">{`
        .top-navigation {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          background-color: #ffffff; /* white as in screenshot */
          border-bottom: 1px solid #e6e6e6; /* subtle border */
          z-index: 1000;
          height: 64px;
          display: flex;
          align-items: center;
        }

        .top-nav-content {
          width: 100%;
          max-width: 1400px;
          margin: 0 auto;
          height: 100%;
          display: flex;
          align-items: center;
          justify-content: space-between;
          padding: 0 20px;
        }

        .top-nav-left {
          width: 200px; /* reserve space for a logo or left gutter */
        }

        .top-nav-right {
          display: flex;
          align-items: center;
          gap: 24px;
          margin-left: auto;
        }

        .nav-links {
          display: flex;
          align-items: center;
          gap: 28px; /* space between links to match screenshot */
        }

        .nav-link {
          color: #333333;
          text-decoration: none;
          font-size: 15px;
          font-weight: 600;
          letter-spacing: 0.2px;
        }

        .nav-link:hover {
          color: #1a73e8; /* subtle hover color */
        }

        .nav-email {
          color: #5a5a5a;
          font-size: 15px;
          white-space: nowrap;
          margin-left: 8px;
        }

        .nav-icon-button {
          color: #6b6b6b;
          padding: 6px;
        }

        .nav-icon-button .icon,
        .nav-icon-button :global(.icon) {
          width: 18px;
          height: 18px;
        }

        @media (max-width: 900px) {
          .nav-links {
            display: none; /* hide links on smaller screens */
          }

          .nav-email {
            display: none; /* hide email on smaller screens */
          }
        }
      `}</style>
    </nav>
  );
};

export default TopNavigation;
